CREATE TABLE "Achats" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Fournisseur" text NOT NULL,
    "TotalAmount" numeric NOT NULL,
    "PaidAmount" numeric NOT NULL,
    "DateAchat" timestamp with time zone NOT NULL,
    "Note" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_Achats" PRIMARY KEY ("Id")
);


CREATE TABLE "AppSettings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Key" text NOT NULL,
    "Value" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_AppSettings" PRIMARY KEY ("Id")
);


CREATE TABLE "CalendarEvents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EventDate" timestamp with time zone NOT NULL,
    "Description" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_CalendarEvents" PRIMARY KEY ("Id")
);


CREATE TABLE "Clients" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Profession" text,
    "MatriculeFiscale" text,
    "Email" text,
    "Telephone" text,
    "Portable" text,
    "Fax" text,
    "Adresse" text,
    "CodePostal" text,
    "Ville" text,
    "Pays" text,
    "Banque" text,
    "RIB" text,
    "Note" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Clients" PRIMARY KEY ("Id")
);


CREATE TABLE "Depenses" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "DateDepense" timestamp with time zone NOT NULL,
    "Libelle" text NOT NULL,
    "Montant" numeric NOT NULL,
    "Description" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_Depenses" PRIMARY KEY ("Id")
);


CREATE TABLE "Produits" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Marque" text,
    "Famille" text,
    "Designation" text NOT NULL,
    "PrixUnitaire" numeric(18,2),
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Produits" PRIMARY KEY ("Id")
);


CREATE TABLE "Roles" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Roles" PRIMARY KEY ("Id")
);


CREATE TABLE "SavingEntries" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Date" date NOT NULL,
    "Amount" numeric(8,2) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_SavingEntries" PRIMARY KEY ("Id")
);


CREATE TABLE "ShowroomArticles" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Slug" character varying(180) NOT NULL,
    "TitleFr" character varying(300) NOT NULL,
    "TitleAr" character varying(300) NOT NULL,
    "ExcerptFr" text,
    "ExcerptAr" text,
    "BodyFr" text,
    "BodyAr" text,
    "CoverImagePath" text,
    "IsPublished" boolean NOT NULL,
    "PublishedAt" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_ShowroomArticles" PRIMARY KEY ("Id")
);


CREATE TABLE "ShowroomBrands" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Slug" character varying(120) NOT NULL,
    "NameFr" character varying(200) NOT NULL,
    "NameAr" character varying(200) NOT NULL,
    "TaglineFr" text,
    "TaglineAr" text,
    "DescriptionFr" text,
    "DescriptionAr" text,
    "LogoImagePath" text,
    "HeroImagePath" text,
    "AccentColor" character varying(32),
    "SortOrder" integer NOT NULL,
    "IsPublished" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_ShowroomBrands" PRIMARY KEY ("Id")
);


CREATE TABLE "ShowroomNavigationItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Key" character varying(120) NOT NULL,
    "LabelFr" character varying(160) NOT NULL,
    "LabelAr" character varying(160) NOT NULL,
    "Url" character varying(500) NOT NULL,
    "IsVisible" boolean NOT NULL,
    "OpenInNewTab" boolean NOT NULL,
    "SortOrder" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_ShowroomNavigationItems" PRIMARY KEY ("Id")
);


CREATE TABLE "ShowroomPageSections" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PageKey" character varying(100) NOT NULL,
    "SectionKey" character varying(120) NOT NULL,
    "SectionType" character varying(80) NOT NULL,
    "TitleFr" text,
    "TitleAr" text,
    "SubtitleFr" text,
    "SubtitleAr" text,
    "BodyFr" text,
    "BodyAr" text,
    "ImagePath" text,
    "MobileImagePath" text,
    "ButtonLabelFr" text,
    "ButtonLabelAr" text,
    "ButtonUrl" text,
    "SecondaryButtonLabelFr" text,
    "SecondaryButtonLabelAr" text,
    "SecondaryButtonUrl" text,
    "StyleVariant" character varying(80),
    "IsVisible" boolean NOT NULL,
    "SortOrder" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_ShowroomPageSections" PRIMARY KEY ("Id")
);


CREATE TABLE "ShowroomRoutines" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Slug" character varying(180) NOT NULL,
    "TitleFr" character varying(240) NOT NULL,
    "TitleAr" character varying(240) NOT NULL,
    "DescriptionFr" text,
    "DescriptionAr" text,
    "HairNeedFr" text,
    "HairNeedAr" text,
    "ImagePath" text,
    "IsPublished" boolean NOT NULL,
    "IsFeatured" boolean NOT NULL,
    "SortOrder" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_ShowroomRoutines" PRIMARY KEY ("Id")
);


CREATE TABLE "ShowroomServices" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Slug" character varying(180) NOT NULL,
    "TitleFr" character varying(240) NOT NULL,
    "TitleAr" character varying(240) NOT NULL,
    "ShortDescriptionFr" text,
    "ShortDescriptionAr" text,
    "DescriptionFr" text,
    "DescriptionAr" text,
    "ImagePath" text,
    "ButtonLabelFr" text,
    "ButtonLabelAr" text,
    "ButtonUrl" text,
    "IsPublished" boolean NOT NULL,
    "SortOrder" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_ShowroomServices" PRIMARY KEY ("Id")
);


CREATE TABLE "ShowroomSiteSettings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Key" character varying(160) NOT NULL,
    "ValueFr" text,
    "ValueAr" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_ShowroomSiteSettings" PRIMARY KEY ("Id")
);


CREATE TABLE "Ventes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ClientId" integer NOT NULL,
    "DocumentNumber" text NOT NULL,
    "FactureNumber" text,
    "TotalAmount" numeric NOT NULL,
    "DateVente" timestamp with time zone NOT NULL,
    "DateLivraison" timestamp with time zone,
    "Etat" integer NOT NULL,
    "PaidAmount" numeric NOT NULL,
    "PaiementEtat" integer NOT NULL,
    "Note" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_Ventes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Ventes_Clients_ClientId" FOREIGN KEY ("ClientId") REFERENCES "Clients" ("Id") ON DELETE CASCADE
);


CREATE TABLE "AchatLignes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "AchatId" integer NOT NULL,
    "ProduitId" integer NOT NULL,
    "Quantite" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_AchatLignes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AchatLignes_Achats_AchatId" FOREIGN KEY ("AchatId") REFERENCES "Achats" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AchatLignes_Produits_ProduitId" FOREIGN KEY ("ProduitId") REFERENCES "Produits" ("Id") ON DELETE CASCADE
);


CREATE TABLE "StockMovements" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProduitId" integer NOT NULL,
    "Quantity" integer NOT NULL,
    "MovementType" text NOT NULL,
    "ReferenceId" integer,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_StockMovements" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_StockMovements_Produits_ProduitId" FOREIGN KEY ("ProduitId") REFERENCES "Produits" ("Id") ON DELETE CASCADE
);


CREATE TABLE "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Username" text NOT NULL,
    "Email" text,
    "PasswordHash" text NOT NULL,
    "RoleId" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Users_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("Id") ON DELETE CASCADE
);


CREATE TABLE "ShowroomRanges" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BrandId" integer NOT NULL,
    "Slug" character varying(120) NOT NULL,
    "NameFr" character varying(200) NOT NULL,
    "NameAr" character varying(200) NOT NULL,
    "DescriptionFr" text,
    "DescriptionAr" text,
    "ImagePath" text,
    "SortOrder" integer NOT NULL,
    "IsPublished" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_ShowroomRanges" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ShowroomRanges_ShowroomBrands_BrandId" FOREIGN KEY ("BrandId") REFERENCES "ShowroomBrands" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Payments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ClientId" integer NOT NULL,
    "VenteId" integer,
    "Amount" numeric NOT NULL,
    "PaymentMode" text NOT NULL,
    "PaymentNumber" text,
    "PaymentDate" timestamp with time zone,
    "DueDate" timestamp with time zone,
    "IsReceived" boolean NOT NULL,
    "CalendarEventId" integer,
    "Note" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Payments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Payments_Clients_ClientId" FOREIGN KEY ("ClientId") REFERENCES "Clients" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Payments_Ventes_VenteId" FOREIGN KEY ("VenteId") REFERENCES "Ventes" ("Id")
);


CREATE TABLE "VenteLignes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "VenteId" integer NOT NULL,
    "ProduitId" integer NOT NULL,
    "Quantite" integer NOT NULL,
    "PrixUnitaire" numeric(18,2),
    "RemisePercent" numeric(5,2) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_VenteLignes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_VenteLignes_Produits_ProduitId" FOREIGN KEY ("ProduitId") REFERENCES "Produits" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_VenteLignes_Ventes_VenteId" FOREIGN KEY ("VenteId") REFERENCES "Ventes" ("Id") ON DELETE CASCADE
);


CREATE TABLE "ShowroomProducts" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BrandId" integer NOT NULL,
    "RangeId" integer,
    "Slug" character varying(180) NOT NULL,
    "NameFr" character varying(240) NOT NULL,
    "NameAr" character varying(240) NOT NULL,
    "CategoryFr" text,
    "CategoryAr" text,
    "HairNeedFr" text,
    "HairNeedAr" text,
    "ShortDescriptionFr" text,
    "ShortDescriptionAr" text,
    "DescriptionFr" text,
    "DescriptionAr" text,
    "HairTypeFr" text,
    "HairTypeAr" text,
    "HowToUseFr" text,
    "HowToUseAr" text,
    "IngredientsFr" text,
    "IngredientsAr" text,
    "Size" text,
    "PriceTnd" numeric(18,2) NOT NULL,
    "AvailabilityFr" text,
    "AvailabilityAr" text,
    "IsAvailable" boolean NOT NULL,
    "IsPublished" boolean NOT NULL,
    "IsFeatured" boolean NOT NULL,
    "IsNew" boolean NOT NULL,
    "SortOrder" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_ShowroomProducts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ShowroomProducts_ShowroomBrands_BrandId" FOREIGN KEY ("BrandId") REFERENCES "ShowroomBrands" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ShowroomProducts_ShowroomRanges_RangeId" FOREIGN KEY ("RangeId") REFERENCES "ShowroomRanges" ("Id") ON DELETE SET NULL
);


CREATE TABLE "ShowroomProductImages" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProductId" integer NOT NULL,
    "ImagePath" character varying(500) NOT NULL,
    "AltTextFr" text,
    "AltTextAr" text,
    "IsPrimary" boolean NOT NULL,
    "SortOrder" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_ShowroomProductImages" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ShowroomProductImages_ShowroomProducts_ProductId" FOREIGN KEY ("ProductId") REFERENCES "ShowroomProducts" ("Id") ON DELETE CASCADE
);


CREATE TABLE "ShowroomRoutineProducts" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoutineId" integer NOT NULL,
    "ProductId" integer NOT NULL,
    "SortOrder" integer NOT NULL,
    "StepLabelFr" text,
    "StepLabelAr" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_ShowroomRoutineProducts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ShowroomRoutineProducts_ShowroomProducts_ProductId" FOREIGN KEY ("ProductId") REFERENCES "ShowroomProducts" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_ShowroomRoutineProducts_ShowroomRoutines_RoutineId" FOREIGN KEY ("RoutineId") REFERENCES "ShowroomRoutines" ("Id") ON DELETE CASCADE
);


